import{_ as a,o as s,c as t,ao as i}from"./chunks/framework.CwrF1Ikc.js";const k=JSON.parse('{"title":"Clusters and data","description":"","frontmatter":{},"headers":[],"relativePath":"clusters.md","filePath":"clusters.md","lastUpdated":null}'),r={name:"clusters.md"};function n(h,e,d,o,l,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="Clusters-and-data" tabindex="-1">Clusters and data <a class="header-anchor" href="#Clusters-and-data" aria-label="Permalink to &quot;Clusters and data {#Clusters-and-data}&quot;">​</a></h1><h2 id="SLURM-jobs" tabindex="-1">SLURM jobs <a class="header-anchor" href="#SLURM-jobs" aria-label="Permalink to &quot;SLURM jobs {#SLURM-jobs}&quot;">​</a></h2><p><a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/tree/main/jobs" target="_blank" rel="noreferrer"><code>jobs/</code></a> has example job scripts for LUMI (<code>lumi.sh</code>, AMD GPUs) and MareNostrum 5 (<code>mn5.sh</code>, NVIDIA GPUs and CPUs up to 16 threads). They run <code>benchmark.sh</code> from the working directory, so submit them from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sbatch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs/mn5.sh</span></span></code></pre></div><p>Adapt the account, partition and <code>WATERLILY_DIR</code> to yours. A few things to keep in mind on a cluster:</p><ul><li><p>Give the job at least one CPU more than the largest <code>-t</code>: the machine check of <code>benchmark.sh</code> stops otherwise (Julia also runs an interactive thread).</p></li><li><p>The first run of a new clone installs the benchmark environment, the first GPU run makes the GPU environment (<code>gpu/CUDA</code> or <code>gpu/AMDGPU</code>), and <code>-u true</code> updates them (see <a href="/WaterLily-Benchmarks/dev/benchmarks#Updating-the-environment">Updating the environment</a>). All of these download packages, so they need internet access.</p></li><li><p><code>mn5.sh</code> sets its own <code>JULIA_DEPOT_PATH</code> for the accelerated partition.</p></li></ul><h2 id="Published-data" tabindex="-1">Published data <a class="header-anchor" href="#Published-data" aria-label="Permalink to &quot;Published data {#Published-data}&quot;">​</a></h2><p>The raw data of studies reported in issues, pull requests or papers are kept in <a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks-data" target="_blank" rel="noreferrer">WaterLily-Benchmarks-data</a>: one folder per study, with the JSON files as <code>benchmark.sh</code> wrote them, the resolved <code>Manifest.toml</code> files, and a README with the hardware, the software versions and the exact commands. <code>compare.jl</code> reads a study&#39;s <code>data/</code> folder directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WATERLILY_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">WaterLily.jl</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> clone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data_dir=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">study</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --speedup_base=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CPUx01,master&quot;</span></span></code></pre></div><p>Use the WaterLily-Benchmarks commit given in the study&#39;s README to get the same tables.</p>',10)])])}const u=a(r,[["render",n]]);export{k as __pageData,u as default};
